-- Inventory & Order Management System
-- Schema followed by the generated FMCG demo seed (3 warehouses, 500 SKUs, 400 PO + 600 SO over six months).
-- Do not edit the generated section by hand: rebuild it with `python3 scripts/build-fmcg-seed.py`.

CREATE TABLE IF NOT EXISTS schema_versions (
    id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    version VARCHAR(50) NOT NULL UNIQUE,
    description VARCHAR(255) NOT NULL,
    applied_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

INSERT INTO schema_versions (version, description)
VALUES ('phase-0', 'Bootstrap schema baseline')
ON DUPLICATE KEY UPDATE description = VALUES(description);

CREATE TABLE IF NOT EXISTS users (
    id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    name VARCHAR(120) NOT NULL,
    email VARCHAR(190) NOT NULL,
    password_hash VARCHAR(255) NOT NULL,
    role ENUM('Admin', 'Sales', 'WarehouseStaff') NOT NULL,
    is_active TINYINT(1) NOT NULL DEFAULT 1,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY uq_users_email (email),
    KEY idx_users_role_active (role, is_active)
) ENGINE=InnoDB;

INSERT INTO schema_versions (version, description)
VALUES ('phase-1', 'Authentication, authorization, and user management baseline')
ON DUPLICATE KEY UPDATE description = VALUES(description);

CREATE TABLE IF NOT EXISTS categories (
    id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    name VARCHAR(120) NOT NULL,
    description VARCHAR(255) NOT NULL DEFAULT '',
    is_active TINYINT(1) NOT NULL DEFAULT 1,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY uq_categories_name (name),
    KEY idx_categories_active (is_active)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS warehouses (
    id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    name VARCHAR(120) NOT NULL,
    location VARCHAR(190) NOT NULL DEFAULT '',
    is_active TINYINT(1) NOT NULL DEFAULT 1,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY uq_warehouses_name (name),
    KEY idx_warehouses_active (is_active)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS products (
    id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    category_id INT UNSIGNED NOT NULL,
    sku VARCHAR(80) NOT NULL,
    name VARCHAR(160) NOT NULL,
    unit VARCHAR(30) NOT NULL,
    purchase_price DECIMAL(14,2) NOT NULL DEFAULT 0.00,
    selling_price DECIMAL(14,2) NOT NULL DEFAULT 0.00,
    price DECIMAL(14,2) NOT NULL DEFAULT 0.00,
    reorder_point INT UNSIGNED NOT NULL DEFAULT 0,
    -- D-17 / ADR-023: a product that tracks expiry needs an expiry date on every new lot (migrated LEGACY lots excepted).
    tracks_expiry TINYINT(1) NOT NULL DEFAULT 0,
    is_active TINYINT(1) NOT NULL DEFAULT 1,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY uq_products_sku (sku),
    KEY idx_products_category_active (category_id, is_active),
    KEY idx_products_name (name),
    CONSTRAINT fk_products_category FOREIGN KEY (category_id) REFERENCES categories (id),
    CONSTRAINT chk_products_purchase_price_non_negative CHECK (purchase_price >= 0),
    CONSTRAINT chk_products_selling_price_non_negative CHECK (selling_price >= 0),
    CONSTRAINT chk_products_price_non_negative CHECK (price >= 0),
    CONSTRAINT chk_products_reorder_non_negative CHECK (reorder_point >= 0)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS product_stocks (
    product_id INT UNSIGNED NOT NULL,
    warehouse_id INT UNSIGNED NOT NULL,
    quantity INT UNSIGNED NOT NULL DEFAULT 0,
    reserved_quantity INT UNSIGNED NOT NULL DEFAULT 0,
    reorder_point_override INT UNSIGNED NULL DEFAULT NULL,
    -- D-17 / ADR-023: number of lots of this pair (= highest stock_lots.lot_seq); lots are locked by (pair, lot_seq).
    lot_count INT UNSIGNED NOT NULL DEFAULT 0,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (product_id, warehouse_id),
    UNIQUE KEY uq_product_stocks_product_warehouse (product_id, warehouse_id),
    KEY idx_product_stocks_warehouse (warehouse_id),
    CONSTRAINT fk_product_stocks_product FOREIGN KEY (product_id) REFERENCES products (id),
    CONSTRAINT fk_product_stocks_warehouse FOREIGN KEY (warehouse_id) REFERENCES warehouses (id),
    CONSTRAINT chk_product_stocks_quantity_non_negative CHECK (quantity >= 0),
    CONSTRAINT chk_product_stocks_reorder_override_non_negative CHECK (reorder_point_override IS NULL OR reorder_point_override >= 0),
    -- D-12 / ADR-018: reserved_quantity is held for Approved sales orders; available = quantity - reserved_quantity.
    CONSTRAINT chk_product_stocks_reserved_lte_quantity CHECK (reserved_quantity <= quantity)
) ENGINE=InnoDB;

-- D-17 / ADR-023: batches/lots per product and warehouse. product_stocks stays the aggregate and the lock root:
-- Σ stock_lots.quantity = product_stocks.quantity per pair, and quantity = opening_quantity + Σ ledger rows of the lot.
-- Identity = code + expiry (NULL as 9999-12-31 via expiry_key, because UNIQUE treats NULLs as distinct) + unit cost (one
-- cost layer per lot for FIFO valuation). Lots are locked by point lookups on (pair, lot_seq), never by range scans.
CREATE TABLE IF NOT EXISTS stock_lots (
    id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    product_id INT UNSIGNED NOT NULL,
    warehouse_id INT UNSIGNED NOT NULL,
    lot_seq INT UNSIGNED NOT NULL,
    lot_code VARCHAR(60) NOT NULL,
    expiry_date DATE NULL DEFAULT NULL,
    expiry_key DATE GENERATED ALWAYS AS (COALESCE(expiry_date, '9999-12-31')) STORED,
    received_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    unit_cost DECIMAL(14,2) NOT NULL,
    quantity INT UNSIGNED NOT NULL DEFAULT 0,
    opening_quantity INT UNSIGNED NOT NULL DEFAULT 0,
    source_type VARCHAR(20) NOT NULL,
    source_id INT UNSIGNED NULL DEFAULT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY uq_stock_lots_seq (product_id, warehouse_id, lot_seq),
    UNIQUE KEY uq_stock_lots_identity (product_id, warehouse_id, lot_code, expiry_key, unit_cost),
    KEY idx_stock_lots_code (lot_code),
    KEY idx_stock_lots_expiry (expiry_date),
    CONSTRAINT fk_stock_lots_pair FOREIGN KEY (product_id, warehouse_id) REFERENCES product_stocks (product_id, warehouse_id),
    CONSTRAINT chk_stock_lots_seq CHECK (lot_seq >= 1),
    CONSTRAINT chk_stock_lots_code CHECK (CHAR_LENGTH(TRIM(lot_code)) >= 1),
    CONSTRAINT chk_stock_lots_cost CHECK (unit_cost >= 0),
    CONSTRAINT chk_stock_lots_quantity CHECK (quantity >= 0 AND opening_quantity >= 0),
    CONSTRAINT chk_stock_lots_opening CHECK (source_type = 'LEGACY' OR opening_quantity = 0),
    -- D-18 / ADR-024: STOCK_COUNT = a lot found by a stock count session and created when the count is posted.
    CONSTRAINT chk_stock_lots_source CHECK (source_type IN ('PO', 'TRANSFER', 'ADJUSTMENT', 'CUSTOMER_RETURN', 'LEGACY', 'RECEIPT', 'STOCK_COUNT'))
) ENGINE=InnoDB;

-- D-17 / ADR-023: ledger rows up to this id were written before the lot migration and may have lot_id NULL; every later
-- row has a lot. A fresh install starts at 0.
CREATE TABLE IF NOT EXISTS stock_lot_watermark (
    id TINYINT UNSIGNED NOT NULL PRIMARY KEY,
    legacy_ledger_max_id BIGINT UNSIGNED NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT chk_stock_lot_watermark_single CHECK (id = 1)
) ENGINE=InnoDB;
INSERT INTO stock_lot_watermark (id, legacy_ledger_max_id) VALUES (1, 0) ON DUPLICATE KEY UPDATE id = id;

-- D-16 / ADR-022: units of measure per product. Every stored stock quantity is an integer in the base unit (the smallest
-- unit, factor 1, unit_code = products.unit). Generated *_key columns let UNIQUE keys enforce exactly one base unit and at
-- most one purchase/sales default per product. A unit without its own price uses base price x factor.
CREATE TABLE IF NOT EXISTS product_units (
    id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    product_id INT UNSIGNED NOT NULL,
    unit_code VARCHAR(30) NOT NULL,
    factor_to_base INT UNSIGNED NOT NULL,
    barcode VARCHAR(64) NULL DEFAULT NULL,
    purchase_price DECIMAL(14,2) NULL DEFAULT NULL,
    selling_price DECIMAL(14,2) NULL DEFAULT NULL,
    is_base TINYINT(1) NOT NULL DEFAULT 0,
    is_purchase_default TINYINT(1) NOT NULL DEFAULT 0,
    is_sales_default TINYINT(1) NOT NULL DEFAULT 0,
    is_active TINYINT(1) NOT NULL DEFAULT 1,
    base_key TINYINT GENERATED ALWAYS AS (IF(is_base = 1, 1, NULL)) STORED,
    purchase_default_key TINYINT GENERATED ALWAYS AS (IF(is_purchase_default = 1, 1, NULL)) STORED,
    sales_default_key TINYINT GENERATED ALWAYS AS (IF(is_sales_default = 1, 1, NULL)) STORED,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY uq_product_units_code (product_id, unit_code),
    UNIQUE KEY uq_product_units_barcode (barcode),
    UNIQUE KEY uq_product_units_base (product_id, base_key),
    UNIQUE KEY uq_product_units_purchase_default (product_id, purchase_default_key),
    UNIQUE KEY uq_product_units_sales_default (product_id, sales_default_key),
    CONSTRAINT fk_product_units_product FOREIGN KEY (product_id) REFERENCES products (id),
    CONSTRAINT chk_product_units_factor CHECK ((is_base = 1 AND factor_to_base = 1) OR (is_base = 0 AND factor_to_base >= 2)),
    CONSTRAINT chk_product_units_base_plain CHECK (is_base = 0 OR (is_active = 1 AND purchase_price IS NULL AND selling_price IS NULL)),
    CONSTRAINT chk_product_units_default_active CHECK (is_active = 1 OR (is_purchase_default = 0 AND is_sales_default = 0)),
    CONSTRAINT chk_product_units_prices CHECK ((purchase_price IS NULL OR purchase_price >= 0) AND (selling_price IS NULL OR selling_price >= 0))
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS suppliers (
    id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    name VARCHAR(120) NOT NULL,
    email VARCHAR(190) NOT NULL DEFAULT '',
    phone VARCHAR(40) NOT NULL DEFAULT '',
    address VARCHAR(255) NOT NULL DEFAULT '',
    is_active TINYINT(1) NOT NULL DEFAULT 1,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY uq_suppliers_name (name),
    KEY idx_suppliers_active (is_active)
) ENGINE=InnoDB;

-- D-19 / ADR-025: customer price lists (one per customer) with quantity tiers per product and unit.
CREATE TABLE IF NOT EXISTS price_lists (
    id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    name VARCHAR(120) NOT NULL,
    description VARCHAR(255) NOT NULL DEFAULT '',
    is_active TINYINT(1) NOT NULL DEFAULT 1,
    valid_from DATE NULL DEFAULT NULL,
    valid_to DATE NULL DEFAULT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY uq_price_lists_name (name),
    CONSTRAINT chk_price_lists_validity CHECK (valid_from IS NULL OR valid_to IS NULL OR valid_to >= valid_from)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS customers (
    id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    name VARCHAR(120) NOT NULL,
    email VARCHAR(190) NOT NULL DEFAULT '',
    phone VARCHAR(40) NOT NULL DEFAULT '',
    address VARCHAR(255) NOT NULL DEFAULT '',
    -- D-19 / ADR-025: assigned price list and optional tax identity (NPWP 15/16 digits, NIK 16 digits), snapshotted on invoices.
    price_list_id INT UNSIGNED NULL DEFAULT NULL,
    npwp VARCHAR(16) NULL DEFAULT NULL,
    nik VARCHAR(16) NULL DEFAULT NULL,
    tax_name VARCHAR(120) NULL DEFAULT NULL,
    tax_address VARCHAR(255) NULL DEFAULT NULL,
    is_active TINYINT(1) NOT NULL DEFAULT 1,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY uq_customers_name (name),
    KEY idx_customers_active (is_active),
    KEY idx_customers_price_list (price_list_id),
    CONSTRAINT fk_customers_price_list FOREIGN KEY (price_list_id) REFERENCES price_lists (id),
    CONSTRAINT chk_customers_npwp CHECK (npwp IS NULL OR npwp REGEXP '^[0-9]{15,16}$'),
    CONSTRAINT chk_customers_nik CHECK (nik IS NULL OR nik REGEXP '^[0-9]{16}$')
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS price_list_items (
    id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    price_list_id INT UNSIGNED NOT NULL,
    product_id INT UNSIGNED NOT NULL,
    unit_code VARCHAR(30) NOT NULL,
    min_quantity INT UNSIGNED NOT NULL DEFAULT 1,
    unit_price DECIMAL(14,2) NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY uq_price_list_items_tier (price_list_id, product_id, unit_code, min_quantity),
    KEY idx_price_list_items_product (product_id, unit_code),
    CONSTRAINT fk_price_list_items_list FOREIGN KEY (price_list_id) REFERENCES price_lists (id),
    CONSTRAINT fk_price_list_items_product FOREIGN KEY (product_id) REFERENCES products (id),
    CONSTRAINT chk_price_list_items_min CHECK (min_quantity >= 1),
    CONSTRAINT chk_price_list_items_price CHECK (unit_price >= 0)
) ENGINE=InnoDB;

