CREATE TABLE IF NOT EXISTS purchase_orders (
    id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    order_number VARCHAR(50) NOT NULL,
    supplier_id INT UNSIGNED NOT NULL,
    destination_warehouse_id INT UNSIGNED NOT NULL,
    status ENUM('Draft', 'Ordered', 'PartiallyReceived', 'Received', 'Cancelled') NOT NULL DEFAULT 'Draft',
    order_date DATE NOT NULL,
    created_by INT UNSIGNED NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY uq_purchase_orders_order_number (order_number),
    KEY idx_purchase_orders_status_date (status, order_date),
    KEY idx_purchase_orders_supplier (supplier_id),
    KEY idx_purchase_orders_warehouse (destination_warehouse_id),
    CONSTRAINT fk_purchase_orders_supplier FOREIGN KEY (supplier_id) REFERENCES suppliers (id),
    CONSTRAINT fk_purchase_orders_warehouse FOREIGN KEY (destination_warehouse_id) REFERENCES warehouses (id),
    CONSTRAINT fk_purchase_orders_created_by FOREIGN KEY (created_by) REFERENCES users (id)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS purchase_order_items (
    id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    purchase_order_id INT UNSIGNED NOT NULL,
    product_id INT UNSIGNED NOT NULL,
    quantity INT UNSIGNED NOT NULL,
    received_quantity INT UNSIGNED NOT NULL DEFAULT 0,
    purchase_price DECIMAL(14,2) NOT NULL DEFAULT 0.00,
    -- D-13 / ADR-019: master purchase price snapshot at draft creation; purchase_price stays the effective line price.
    list_price DECIMAL(14,2) NOT NULL,
    price_reason VARCHAR(255) NULL DEFAULT NULL,
    -- D-16 / ADR-022: unit snapshot. quantity/received_quantity are base units; prices are per entered unit.
    unit_code VARCHAR(30) NOT NULL,
    unit_factor INT UNSIGNED NOT NULL DEFAULT 1,
    unit_quantity INT UNSIGNED NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY uq_purchase_order_items_po_product (purchase_order_id, product_id),
    KEY idx_purchase_order_items_product (product_id),
    CONSTRAINT fk_purchase_order_items_order FOREIGN KEY (purchase_order_id) REFERENCES purchase_orders (id) ON DELETE CASCADE,
    CONSTRAINT fk_purchase_order_items_product FOREIGN KEY (product_id) REFERENCES products (id),
    CONSTRAINT chk_purchase_order_items_quantity_positive CHECK (quantity > 0),
    CONSTRAINT chk_purchase_order_items_received_non_negative CHECK (received_quantity >= 0),
    CONSTRAINT chk_purchase_order_items_price_non_negative CHECK (purchase_price >= 0),
    CONSTRAINT chk_purchase_order_items_list_price_non_negative CHECK (list_price >= 0),
    CONSTRAINT chk_purchase_order_items_price_reason CHECK ((purchase_price = list_price AND price_reason IS NULL) OR (purchase_price <> list_price AND price_reason IS NOT NULL AND CHAR_LENGTH(TRIM(price_reason)) >= 3)),
    CONSTRAINT chk_purchase_order_items_received_lte_quantity CHECK (received_quantity <= quantity),
    CONSTRAINT chk_purchase_order_items_unit_factor CHECK (unit_factor >= 1),
    CONSTRAINT chk_purchase_order_items_unit_quantity CHECK (unit_quantity > 0 AND quantity = unit_quantity * unit_factor),
    CONSTRAINT chk_purchase_order_items_received_whole_units CHECK (MOD(received_quantity, unit_factor) = 0)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS stock_ledger (
    id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    product_id INT UNSIGNED NOT NULL,
    warehouse_id INT UNSIGNED NOT NULL,
    movement_type ENUM('Receipt', 'Issue', 'Adjustment') NOT NULL,
    quantity INT UNSIGNED NOT NULL,
    quantity_delta BIGINT NULL,
    reference_type VARCHAR(20) NOT NULL,
    reference_id INT UNSIGNED NOT NULL,
    performed_by INT UNSIGNED NOT NULL,
    -- D-17 / ADR-023: the lot moved; NULL only for rows written before the lot migration (see stock_lot_watermark).
    lot_id INT UNSIGNED NULL DEFAULT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    -- D-20 / ADR-026: FIFO-per-batch valuation. A row with a lot carries the lot's unit cost (per base unit) and
    -- cost_amount = signed quantity x unit_cost in whole cents (Receipt +, Issue -, Adjustment = sign of quantity_delta).
    -- Rows before the valuation start (lot_id NULL, up to stock_lot_watermark) carry no cost and are never given one.
    unit_cost DECIMAL(14,2) NULL DEFAULT NULL,
    cost_amount DECIMAL(24,2) NULL DEFAULT NULL,
    KEY idx_stock_ledger_product_warehouse (product_id, warehouse_id),
    KEY idx_stock_ledger_reference (reference_type, reference_id),
    KEY idx_stock_ledger_lot (lot_id, id),
    KEY idx_stock_ledger_created (created_at),
    CONSTRAINT fk_stock_ledger_lot FOREIGN KEY (lot_id) REFERENCES stock_lots (id),
    CONSTRAINT fk_stock_ledger_product FOREIGN KEY (product_id) REFERENCES products (id),
    CONSTRAINT fk_stock_ledger_warehouse FOREIGN KEY (warehouse_id) REFERENCES warehouses (id),
    CONSTRAINT fk_stock_ledger_performed_by FOREIGN KEY (performed_by) REFERENCES users (id),
    CONSTRAINT chk_stock_ledger_quantity_positive CHECK (quantity > 0),
    CONSTRAINT chk_stock_ledger_direction CHECK ((movement_type='Adjustment' AND quantity_delta IS NOT NULL AND ABS(quantity_delta)=quantity) OR (movement_type<>'Adjustment' AND quantity_delta IS NULL)),
    CONSTRAINT chk_stock_ledger_cost CHECK ((lot_id IS NULL AND unit_cost IS NULL AND cost_amount IS NULL)
        OR (lot_id IS NOT NULL AND unit_cost IS NOT NULL AND unit_cost >= 0 AND cost_amount IS NOT NULL
            AND cost_amount = (CASE movement_type WHEN 'Receipt' THEN CAST(quantity AS SIGNED) WHEN 'Issue' THEN -CAST(quantity AS SIGNED) ELSE quantity_delta END) * unit_cost))
) ENGINE=InnoDB;

ALTER TABLE stock_ledger MODIFY movement_type ENUM('Receipt', 'Issue', 'Adjustment') NOT NULL;

