CREATE TABLE IF NOT EXISTS audit_logs (
    id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    actor_id INT UNSIGNED NULL,
    action VARCHAR(80) NOT NULL,
    entity_type VARCHAR(80) NOT NULL,
    entity_id INT UNSIGNED NULL,
    status ENUM('success', 'failure', 'blocked') NOT NULL,
    ip_address VARCHAR(45) NOT NULL DEFAULT '',
    user_agent VARCHAR(255) NOT NULL DEFAULT '',
    metadata_json JSON NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    KEY idx_audit_logs_actor_time (actor_id, created_at),
    KEY idx_audit_logs_entity_time (entity_type, entity_id, created_at),
    KEY idx_audit_logs_action_time (action, created_at),
    CONSTRAINT fk_audit_logs_actor FOREIGN KEY (actor_id) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS login_attempts (
    id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    email VARCHAR(190) NOT NULL,
    ip_address VARCHAR(45) NOT NULL,
    successful TINYINT(1) NOT NULL DEFAULT 0,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    KEY idx_login_attempts_subject_time (email, ip_address, created_at),
    KEY idx_login_attempts_created_at (created_at)
) ENGINE=InnoDB;

INSERT INTO schema_versions (version, description)
VALUES ('enterprise-security-1', 'Audit log and login attempt tables')
ON DUPLICATE KEY UPDATE description = VALUES(description);

-- D-19 / ADR-025: quotations (QT-YYMM-NNNN); Expired is computed from valid_until at read time, not stored.
CREATE TABLE IF NOT EXISTS quotations (
    id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    quotation_number VARCHAR(50) NOT NULL,
    customer_id INT UNSIGNED NOT NULL,
    source_warehouse_id INT UNSIGNED NOT NULL,
    status ENUM('Draft', 'Sent', 'Accepted', 'Rejected', 'Cancelled') NOT NULL DEFAULT 'Draft',
    quote_date DATE NOT NULL,
    valid_until DATE NOT NULL,
    notes VARCHAR(500) NOT NULL DEFAULT '',
    created_by INT UNSIGNED NOT NULL,
    sent_at TIMESTAMP NULL DEFAULT NULL,
    decided_by INT UNSIGNED NULL DEFAULT NULL,
    decided_at TIMESTAMP NULL DEFAULT NULL,
    rejection_reason VARCHAR(500) NULL DEFAULT NULL,
    cancelled_by INT UNSIGNED NULL DEFAULT NULL,
    cancelled_at TIMESTAMP NULL DEFAULT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY uq_quotations_number (quotation_number),
    KEY idx_quotations_status_date (status, quote_date),
    KEY idx_quotations_customer (customer_id),
    KEY idx_quotations_created_by (created_by),
    CONSTRAINT fk_quotations_customer FOREIGN KEY (customer_id) REFERENCES customers (id),
    CONSTRAINT fk_quotations_warehouse FOREIGN KEY (source_warehouse_id) REFERENCES warehouses (id),
    CONSTRAINT fk_quotations_created_by FOREIGN KEY (created_by) REFERENCES users (id),
    CONSTRAINT fk_quotations_decided_by FOREIGN KEY (decided_by) REFERENCES users (id),
    CONSTRAINT fk_quotations_cancelled_by FOREIGN KEY (cancelled_by) REFERENCES users (id),
    CONSTRAINT chk_quotations_validity CHECK (valid_until >= quote_date),
    CONSTRAINT chk_quotations_sent CHECK (status IN ('Draft', 'Cancelled') OR sent_at IS NOT NULL),
    CONSTRAINT chk_quotations_decided CHECK (status NOT IN ('Accepted', 'Rejected') OR (decided_by IS NOT NULL AND decided_at IS NOT NULL)),
    CONSTRAINT chk_quotations_rejected CHECK ((status = 'Rejected') = (rejection_reason IS NOT NULL)),
    CONSTRAINT chk_quotations_cancelled CHECK ((status = 'Cancelled') = (cancelled_by IS NOT NULL AND cancelled_at IS NOT NULL))
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS quotation_items (
    id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    quotation_id INT UNSIGNED NOT NULL,
    product_id INT UNSIGNED NOT NULL,
    quantity INT UNSIGNED NOT NULL,
    unit_code VARCHAR(30) NOT NULL,
    unit_factor INT UNSIGNED NOT NULL DEFAULT 1,
    unit_quantity INT UNSIGNED NOT NULL,
    unit_price DECIMAL(14,2) NOT NULL,
    list_price DECIMAL(14,2) NOT NULL,
    price_reason VARCHAR(255) NULL DEFAULT NULL,
    price_source ENUM('MASTER', 'PRICE_LIST') NOT NULL DEFAULT 'MASTER',
    price_list_id INT UNSIGNED NULL DEFAULT NULL,
    UNIQUE KEY uq_quotation_items_product (quotation_id, product_id),
    KEY idx_quotation_items_product (product_id),
    CONSTRAINT fk_quotation_items_quotation FOREIGN KEY (quotation_id) REFERENCES quotations (id),
    CONSTRAINT fk_quotation_items_product FOREIGN KEY (product_id) REFERENCES products (id),
    CONSTRAINT fk_quotation_items_price_list FOREIGN KEY (price_list_id) REFERENCES price_lists (id),
    CONSTRAINT chk_quotation_items_unit CHECK (unit_factor >= 1 AND unit_quantity > 0 AND quantity = unit_quantity * unit_factor),
    CONSTRAINT chk_quotation_items_prices CHECK (unit_price >= 0 AND list_price >= 0),
    CONSTRAINT chk_quotation_items_reason CHECK ((unit_price = list_price AND price_reason IS NULL) OR (unit_price <> list_price AND price_reason IS NOT NULL AND CHAR_LENGTH(TRIM(price_reason)) >= 3)),
    CONSTRAINT chk_quotation_items_source CHECK ((price_source = 'MASTER' AND price_list_id IS NULL) OR (price_source = 'PRICE_LIST' AND price_list_id IS NOT NULL))
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS sales_orders (
    id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    order_number VARCHAR(50) NOT NULL,
    customer_id INT UNSIGNED NOT NULL,
    source_warehouse_id INT UNSIGNED NOT NULL,
    -- PartiallyFulfilled: D-14 / ADR-020 (user decision outside the brief's SO status set).
    status ENUM('Draft', 'PendingApproval', 'Approved', 'PartiallyFulfilled', 'Fulfilled', 'Cancelled') NOT NULL DEFAULT 'Draft',
    order_date DATE NOT NULL,
    created_by INT UNSIGNED NOT NULL,
    approved_by INT UNSIGNED NULL,
    approved_at TIMESTAMP NULL,
    -- D-19 / ADR-025: the accepted quotation this draft was converted from; UNIQUE = one SO per quotation.
    quotation_id INT UNSIGNED NULL DEFAULT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY uq_sales_orders_order_number (order_number),
    UNIQUE KEY uq_sales_orders_quotation (quotation_id),
    KEY idx_sales_orders_status_date (status, order_date),
    KEY idx_sales_orders_customer (customer_id),
    KEY idx_sales_orders_warehouse (source_warehouse_id),
    KEY idx_sales_orders_created_by (created_by),
    CONSTRAINT fk_sales_orders_customer FOREIGN KEY (customer_id) REFERENCES customers (id),
    CONSTRAINT fk_sales_orders_warehouse FOREIGN KEY (source_warehouse_id) REFERENCES warehouses (id),
    CONSTRAINT fk_sales_orders_created_by FOREIGN KEY (created_by) REFERENCES users (id),
    CONSTRAINT fk_sales_orders_approved_by FOREIGN KEY (approved_by) REFERENCES users (id),
    CONSTRAINT fk_sales_orders_quotation FOREIGN KEY (quotation_id) REFERENCES quotations (id)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS sales_order_items (
    id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    sales_order_id INT UNSIGNED NOT NULL,
    product_id INT UNSIGNED NOT NULL,
    quantity INT UNSIGNED NOT NULL,
    selling_price DECIMAL(14,2) NOT NULL DEFAULT 0.00,
    -- D-13 / ADR-019: master selling price snapshot at draft creation; selling_price stays the effective line price.
    list_price DECIMAL(14,2) NOT NULL,
    price_reason VARCHAR(255) NULL DEFAULT NULL,
    -- D-19 / ADR-025: list_price is the resolved price (customer price list tier, else master); converted lines name their quotation line.
    price_source ENUM('MASTER', 'PRICE_LIST') NOT NULL DEFAULT 'MASTER',
    price_list_id INT UNSIGNED NULL DEFAULT NULL,
    quotation_item_id INT UNSIGNED NULL DEFAULT NULL,
    -- D-14 / ADR-020: units already issued over one or more shipments; remaining = quantity - issued_quantity.
    issued_quantity INT UNSIGNED NOT NULL DEFAULT 0,
    -- D-16 / ADR-022: unit snapshot. quantity/issued_quantity are base units; prices are per entered unit.
    unit_code VARCHAR(30) NOT NULL,
    unit_factor INT UNSIGNED NOT NULL DEFAULT 1,
    unit_quantity INT UNSIGNED NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY uq_sales_order_items_so_product (sales_order_id, product_id),
    UNIQUE KEY uq_sales_order_items_quotation_item (quotation_item_id),
    KEY idx_sales_order_items_product (product_id),
    CONSTRAINT fk_sales_order_items_order FOREIGN KEY (sales_order_id) REFERENCES sales_orders (id) ON DELETE CASCADE,
    CONSTRAINT fk_sales_order_items_product FOREIGN KEY (product_id) REFERENCES products (id),
    CONSTRAINT chk_sales_order_items_quantity_positive CHECK (quantity > 0),
    CONSTRAINT chk_sales_order_items_price_non_negative CHECK (selling_price >= 0),
    CONSTRAINT chk_sales_order_items_list_price_non_negative CHECK (list_price >= 0),
    CONSTRAINT chk_sales_order_items_price_reason CHECK ((selling_price = list_price AND price_reason IS NULL) OR (selling_price <> list_price AND price_reason IS NOT NULL AND CHAR_LENGTH(TRIM(price_reason)) >= 3)),
    CONSTRAINT chk_sales_order_items_issued_lte_quantity CHECK (issued_quantity <= quantity),
    CONSTRAINT chk_sales_order_items_unit_factor CHECK (unit_factor >= 1),
    CONSTRAINT chk_sales_order_items_unit_quantity CHECK (unit_quantity > 0 AND quantity = unit_quantity * unit_factor),
    CONSTRAINT chk_sales_order_items_issued_whole_units CHECK (MOD(issued_quantity, unit_factor) = 0),
    CONSTRAINT fk_sales_order_items_price_list FOREIGN KEY (price_list_id) REFERENCES price_lists (id),
    CONSTRAINT fk_sales_order_items_quotation_item FOREIGN KEY (quotation_item_id) REFERENCES quotation_items (id),
    CONSTRAINT chk_sales_order_items_price_source CHECK ((price_source = 'MASTER' AND price_list_id IS NULL) OR (price_source = 'PRICE_LIST' AND price_list_id IS NOT NULL))
) ENGINE=InnoDB;

INSERT INTO schema_versions (version, description)
VALUES ('phase-4', 'Sales order approval and concurrency-safe issue baseline')
ON DUPLICATE KEY UPDATE description = VALUES(description);

CREATE TABLE IF NOT EXISTS operation_requests (
    id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    actor_id INT UNSIGNED NOT NULL,
    request_key CHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    payload_hash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    completed BOOLEAN NOT NULL DEFAULT FALSE,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY uq_operation_request_actor_key (actor_id, request_key),
    CONSTRAINT fk_operation_request_actor FOREIGN KEY (actor_id) REFERENCES users(id)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS purchase_order_closures (
 purchase_order_id INT UNSIGNED PRIMARY KEY, closed_by INT UNSIGNED NOT NULL,
 reason VARCHAR(500) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY (purchase_order_id) REFERENCES purchase_orders(id), FOREIGN KEY (closed_by) REFERENCES users(id)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS sales_order_rejections (
 sales_order_id INT UNSIGNED PRIMARY KEY, rejected_by INT UNSIGNED NOT NULL,
 reason VARCHAR(500) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY (sales_order_id) REFERENCES sales_orders(id), FOREIGN KEY (rejected_by) REFERENCES users(id)
) ENGINE=InnoDB;
-- D-14 / ADR-020: closed remaining fulfilment of a PartiallyFulfilled sales order (mirror of purchase_order_closures).
CREATE TABLE IF NOT EXISTS sales_order_closures (
 sales_order_id INT UNSIGNED PRIMARY KEY, closed_by INT UNSIGNED NOT NULL,
 reason VARCHAR(500) NOT NULL, closed_units INT UNSIGNED NOT NULL,
 created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
 CONSTRAINT fk_sales_order_closures_order FOREIGN KEY (sales_order_id) REFERENCES sales_orders(id),
 CONSTRAINT fk_sales_order_closures_closed_by FOREIGN KEY (closed_by) REFERENCES users(id),
 CONSTRAINT chk_sales_order_closures_units CHECK (closed_units > 0)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS inventory_operations (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 kind ENUM('Adjustment','Transfer','SupplierReturn','CustomerReturn') NOT NULL,
 status ENUM('PendingApproval','Approved','Rejected','Posted','Cancelled','Dispatched','Received') NOT NULL DEFAULT 'PendingApproval',
 warehouse_id INT UNSIGNED NOT NULL, destination_id INT UNSIGNED NULL,
 reason VARCHAR(500) NOT NULL, decision_reason VARCHAR(500) NULL,
 condition_confirmed BOOLEAN NOT NULL DEFAULT FALSE,
 created_by INT UNSIGNED NOT NULL, approved_by INT UNSIGNED NULL, posted_by INT UNSIGNED NULL,
 created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, approved_at TIMESTAMP NULL, posted_at TIMESTAMP NULL,
 dispatched_by INT UNSIGNED NULL, dispatched_at TIMESTAMP NULL,
 received_by INT UNSIGNED NULL, received_at TIMESTAMP NULL, receipt_reason VARCHAR(500) NULL,
 -- D-17 / ADR-023: an Adjustment may be the Admin-approved write-off of expired lots (same flow, one line per lot).
 purpose ENUM('Standard','ExpiredWriteOff') NOT NULL DEFAULT 'Standard',
 KEY idx_inventory_operations_status_time (status,created_at),
 FOREIGN KEY (warehouse_id) REFERENCES warehouses(id), FOREIGN KEY (destination_id) REFERENCES warehouses(id),
 FOREIGN KEY (created_by) REFERENCES users(id), FOREIGN KEY (approved_by) REFERENCES users(id), FOREIGN KEY (posted_by) REFERENCES users(id),
 CONSTRAINT fk_inventory_operations_dispatched_by FOREIGN KEY (dispatched_by) REFERENCES users(id),
 CONSTRAINT fk_inventory_operations_received_by FOREIGN KEY (received_by) REFERENCES users(id),
 CONSTRAINT chk_return_condition CHECK (kind<>'CustomerReturn' OR condition_confirmed=TRUE),
 CONSTRAINT chk_operation_independent_approval CHECK (approved_by IS NULL OR approved_by <> created_by),
 CONSTRAINT chk_operation_transfer_destination CHECK ((kind='Transfer' AND destination_id IS NOT NULL AND destination_id<>warehouse_id) OR (kind<>'Transfer' AND destination_id IS NULL)),
 -- D-15 / ADR-021: transfers go Approved -> Dispatched -> Received (never Posted); other kinds never use the transit statuses.
 CONSTRAINT chk_operation_transit_status CHECK ((kind='Transfer' AND status<>'Posted') OR (kind<>'Transfer' AND status NOT IN ('Dispatched','Received'))),
 CONSTRAINT chk_operation_purpose CHECK (purpose='Standard' OR kind='Adjustment'),
 CONSTRAINT chk_operation_transit_stamps CHECK (((status IN ('Dispatched','Received')) = (dispatched_by IS NOT NULL AND dispatched_at IS NOT NULL)) AND ((status='Received') = (received_by IS NOT NULL AND received_at IS NOT NULL)))
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS inventory_operation_items (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, operation_id INT UNSIGNED NOT NULL,
 product_id INT UNSIGNED NOT NULL, quantity INT UNSIGNED NOT NULL,
 baseline INT UNSIGNED NULL, source_ledger_id BIGINT UNSIGNED NULL,
 -- D-15 / ADR-021: transfer line progress. In transit = dispatched - received - damaged - short (written off: damaged + short).
 dispatched_quantity INT UNSIGNED NULL, received_quantity INT UNSIGNED NULL, damaged_quantity INT UNSIGNED NULL, short_quantity INT UNSIGNED NULL,
 -- D-16 / ADR-022: unit snapshot of the line; quantity, baseline and transit fields are base units.
 unit_code VARCHAR(30) NOT NULL, unit_factor INT UNSIGNED NOT NULL DEFAULT 1, unit_quantity INT UNSIGNED NOT NULL,
 -- D-17 / ADR-023: an adjustment line counts one existing lot (lot_id) or creates a new one (lot_code/expiry_date); a line
 -- without either is a pair-level count. lot_key makes the line unique per product and lot.
 lot_id INT UNSIGNED NULL, lot_code VARCHAR(60) NULL, expiry_date DATE NULL,
 lot_key INT UNSIGNED GENERATED ALWAYS AS (COALESCE(lot_id, 0)) STORED,
 UNIQUE KEY uq_operation_product_lot (operation_id,product_id,lot_key), KEY idx_operation_source (source_ledger_id),
 FOREIGN KEY (operation_id) REFERENCES inventory_operations(id), FOREIGN KEY (product_id) REFERENCES products(id),
 FOREIGN KEY (source_ledger_id) REFERENCES stock_ledger(id),
 CONSTRAINT chk_operation_items_dispatched CHECK (dispatched_quantity IS NULL OR dispatched_quantity = quantity),
 CONSTRAINT chk_operation_items_receipt CHECK ((received_quantity IS NULL AND damaged_quantity IS NULL AND short_quantity IS NULL)
   OR (dispatched_quantity IS NOT NULL AND received_quantity IS NOT NULL AND damaged_quantity IS NOT NULL AND short_quantity IS NOT NULL
       AND received_quantity + damaged_quantity + short_quantity = dispatched_quantity)),
 CONSTRAINT chk_operation_items_unit CHECK (unit_factor >= 1 AND quantity = unit_quantity * unit_factor),
 CONSTRAINT fk_operation_items_lot FOREIGN KEY (lot_id) REFERENCES stock_lots(id),
 CONSTRAINT chk_operation_items_lot CHECK (lot_id IS NULL OR lot_code IS NULL),
 CONSTRAINT chk_operation_items_lot_expiry CHECK (expiry_date IS NULL OR lot_code IS NOT NULL)
) ENGINE=InnoDB;

-- D-17 / ADR-023: lots carried by a transfer line. Dispatch writes one row per source lot (FEFO); receipt records per lot
-- the good/damaged/short units and the destination lot (same code, expiry and unit cost).
CREATE TABLE IF NOT EXISTS inventory_operation_lots (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 operation_id INT UNSIGNED NOT NULL, operation_item_id BIGINT UNSIGNED NOT NULL, product_id INT UNSIGNED NOT NULL,
 source_lot_id INT UNSIGNED NOT NULL, lot_code VARCHAR(60) NOT NULL, expiry_date DATE NULL, unit_cost DECIMAL(14,2) NOT NULL,
 dispatched_quantity INT UNSIGNED NOT NULL,
 received_quantity INT UNSIGNED NULL, damaged_quantity INT UNSIGNED NULL, short_quantity INT UNSIGNED NULL,
 destination_lot_id INT UNSIGNED NULL,
 UNIQUE KEY uq_operation_lots_item_lot (operation_item_id, source_lot_id),
 KEY idx_operation_lots_operation (operation_id),
 KEY idx_operation_lots_destination (destination_lot_id),
 CONSTRAINT fk_operation_lots_operation FOREIGN KEY (operation_id) REFERENCES inventory_operations(id),
 CONSTRAINT fk_operation_lots_item FOREIGN KEY (operation_item_id) REFERENCES inventory_operation_items(id),
 CONSTRAINT fk_operation_lots_source FOREIGN KEY (source_lot_id) REFERENCES stock_lots(id),
 CONSTRAINT fk_operation_lots_destination FOREIGN KEY (destination_lot_id) REFERENCES stock_lots(id),
 CONSTRAINT chk_operation_lots_dispatched CHECK (dispatched_quantity > 0),
 CONSTRAINT chk_operation_lots_receipt CHECK ((received_quantity IS NULL AND damaged_quantity IS NULL AND short_quantity IS NULL)
   OR (received_quantity IS NOT NULL AND damaged_quantity IS NOT NULL AND short_quantity IS NOT NULL
       AND received_quantity + damaged_quantity + short_quantity = dispatched_quantity)),
 CONSTRAINT chk_operation_lots_destination CHECK (destination_lot_id IS NULL OR received_quantity > 0)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS inventory_return_totals (
 source_ledger_id BIGINT UNSIGNED PRIMARY KEY, returned_quantity INT UNSIGNED NOT NULL DEFAULT 0,
 FOREIGN KEY (source_ledger_id) REFERENCES stock_ledger(id)
) ENGINE=InnoDB;

