VALUES ('reorder-override-1', 'Per-warehouse reorder point override (D-10, ADR-016)')
ON DUPLICATE KEY UPDATE description = VALUES(description);

-- D-11 / ADR-017: server-assigned order numbers PREFIX-YYMM-NNNN. One counter per prefix and month (YYMM): PO/SO, and
-- since D-19 / ADR-025 QT (quotation), DO (delivery note) and INV (invoice);
-- claimed with the draft insert in one transaction. order_number stays UNIQUE as the final guard.
CREATE TABLE IF NOT EXISTS document_sequences (
    prefix VARCHAR(10) NOT NULL,
    period CHAR(4) NOT NULL,
    last_number INT UNSIGNED NOT NULL,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (prefix, period),
    CONSTRAINT chk_document_sequences_prefix CHECK (prefix IN ('PO', 'SO', 'QT', 'DO', 'INV')),
    CONSTRAINT chk_document_sequences_period CHECK (period REGEXP '^[0-9]{4}$')
) ENGINE=InnoDB;

INSERT INTO schema_versions (version, description)
VALUES ('order-number-1', 'Server-assigned order numbers PO/SO-YYMM-NNNN (D-11, ADR-017)')
ON DUPLICATE KEY UPDATE description = VALUES(description);

